function mediaUrlsInDom(root=document){const urls=new Set();root.querySelectorAll('[style*="background-image"],img[src]').forEach(el=>{if(el.tagName==='IMG'&&el.src)urls.add(el.src);const bg=el.style?.backgroundImage||getComputedStyle(el).backgroundImage||'';for(const match of bg.matchAll(/url\(["']?([^"')]+)["']?\)/g))if(match[1]&&!match[1].startsWith('data:')&&!match[1].startsWith('blob:'))urls.add(match[1]);});return [...urls];}
