function parseCsvLine(line,separator){const out=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===separator&&!quoted){out.push(value.trim());value='';}else value+=c;}out.push(value.trim());return out;}
function parseCatalogCsv(text){const lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)throw new Error('Le CSV doit contenir un en-tête et au moins une production.');const separator=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';const headers=parseCsvLine(lines[0],separator).map(x=>x.toLowerCase().trim());const required=['title','bpm','key','genre'];for(const field of required)if(!headers.includes(field))throw new Error(`Colonne obligatoire manquante : ${field}`);return lines.slice(1).map(line=>{const values=parseCsvLine(line,separator),row={};headers.forEach((h,i)=>row[h]=values[i]||'');return row;}).filter(row=>row.title);}
