function serializeDraftForm(form){
 const values={};
 for(const element of [...form.elements]){
  if(!element.name||element.disabled||element.type==='file'||element.type==='password'||element.type==='submit'||element.type==='button')continue;
  if(element.type==='checkbox')values[element.name]=element.checked;
  else if(element.type==='radio'){if(element.checked)values[element.name]=element.value;}
  else values[element.name]=element.value;
 }
 return {savedAt:Date.now(),values};
}
function restoreDraftForm(form,key){
 try{
  const draft=JSON.parse(localStorage.getItem(key)||'null');
  if(!draft?.values||Date.now()-Number(draft.savedAt||0)>7*86400000)return false;
  for(const [name,value] of Object.entries(draft.values)){
   const elements=form.querySelectorAll(`[name="${CSS.escape(name)}"]`);
   elements.forEach(element=>{if(element.type==='checkbox')element.checked=Boolean(value);else if(element.type==='radio')element.checked=String(element.value)===String(value);else element.value=value??'';});
  }
  form.dispatchEvent(new Event('input',{bubbles:true}));
  return true;
 }catch{return false;}
}
function clearAutoDraft(form){
 const key=form?.dataset?.autoDraftKey||state.activeDraftKey;
 if(key)localStorage.removeItem(key);
 if(form?._autoDraftTimer)clearTimeout(form._autoDraftTimer);
 clearTimeout(state.autoDraftTimer);state.activeDraftKey='';state.formDirty=false;
}
function setupAutoDraft(form,name){
 if(!form||form.dataset.autoDraftReady==='true')return;
 const key=formDraftKey(form,name);form.dataset.autoDraftKey=key;form.dataset.autoDraftReady='true';state.activeDraftKey=key;
 const restored=restoreDraftForm(form,key);state.formDirty=false;
 if(restored)setTimeout(()=>toast('Brouillon local restauré automatiquement'),300);
 form.addEventListener('input',event=>{
  if(event.target?.type==='password')return;
  state.formDirty=true;clearTimeout(form._autoDraftTimer);
  form._autoDraftTimer=setTimeout(()=>runWhenBrowserIdle(()=>{
   try{localStorage.setItem(key,JSON.stringify(serializeDraftForm(form)));const indicator=form.querySelector('[data-autosave-status]')||document.querySelector('[data-autosave-status]');if(indicator)indicator.textContent=`Brouillon local sauvegardé à ${new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}`;}catch(error){console.warn('Brouillon local non sauvegardé',error);}
  },1600),1050);
 });
 form.addEventListener('change',()=>{state.formDirty=true;});
 const actions=form.querySelector('.editor-actions,.settings-actions,.onboarding-actions')||form;
 if(!actions.querySelector('[data-autosave-status]'))actions.insertAdjacentHTML('beforeend','<small class="autosave-status" data-autosave-status>Sauvegarde automatique activée</small>');
}
function setupPageAutoDrafts(){
 const pairs=[['production-form','production'],['profile-customizer','profile'],['aspect-form','aspect'],['settings-account-form','settings-account'],['settings-notifications-form','settings-notifications'],['settings-privacy-form','settings-privacy'],['settings-integrations-form','settings-integrations'],['announcement-form','announcement'],['playlist-form','playlist'],['onboarding-form','onboarding']];
 pairs.forEach(([id,name])=>setupAutoDraft(document.getElementById(id),name));
}
function confirmDiscardChanges(){
 if(!state.formDirty)return true;
 if(!confirm('Des modifications ne sont pas encore enregistrées. Quitter cette page et les conserver uniquement comme brouillon local ?'))return false;
 state.formDirty=false;return true;
}
function initials(name){return String(name||'DR').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();}
function mediaUrl(value,version=''){
 const raw=String(value||'').trim();if(!raw)return'';if(raw.startsWith('data:')||raw.startsWith('blob:'))return raw;
 try{const u=new URL(raw,location.href);if(version)u.searchParams.set('v',String(version).replace(/[^a-zA-Z0-9_.:-]/g,''));return u.href;}catch{return raw;}
}
function imageBackground(value,version='',fit='cover',position='center'){const url=mediaUrl(value,version);return url?`background-image:url('${esc(url)}');background-size:${esc(fit)};background-position:${esc(position)};background-repeat:no-repeat;`:'';}
function profileAvatar(p,size=''){const image=mediaUrl(p?.avatar,p?.updated_at||p?.avatar_version||'');const accent=p?.theme?.accent||p?.theme?.secondary||'#30333b';const style=image?`background-image:url('${esc(image)}')`:`background:${esc(accent)}`;const userId=p?.user_id||p?.id||'';return `<span class="avatar ${size} ${image?'has-image':'avatar-placeholder'} ${isUserOnline(userId)?'online':''}" data-presence-user="${esc(userId)}" style="${style}" aria-label="${esc(p?.name||'Profil')}"></span>`;}
function sectionTitle(title,subtitle='',action=''){return `<div class="section-title"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>`;}
function statusClass(v){return v==='Publié'||v==='Acceptée'||v==='Validé'?'success':v==='Expiré'||v==='Refusée'||v==='Annulée'?'danger':v==='Réservé'||v==='En discussion'||v==='En attente'?'warning':'';}
function isAdmin(user=state.user){return Boolean(user&&(user.is_admin||user.role==='Admin'));}
function rolesOf(user=state.user){const roles=Array.isArray(user?.roles)&&user.roles.length?user.roles:(user?.role&&user.role!=='Admin'?[user.role]:[]);return [...new Set(roles.filter(Boolean))];}
function hasRole(role,user=state.user){if(user===state.user&&state.viewAsRole)return state.viewAsRole===role;return Boolean(isAdmin(user)||rolesOf(user).includes(role));}
function rolesLabel(user=state.user){const list=rolesOf(user);return [isAdmin(user)?'Admin':'',...list].filter(Boolean).join(' · ')||'Membre';}
function authUserId(user=state.user){return String(user?.user_id||user?.auth_user_id||user?.id||'').trim();}
function normalizeStateUser(){if(!state.user)return null;const uid=authUserId(state.user);if(state.user.user_id&&state.user.id!==state.user.user_id)state.user={...state.user,profile_id:state.user.profile_id||state.user.id,id:state.user.user_id};else if(uid&&!state.user.user_id)state.user={...state.user,user_id:uid};return state.user;}
async function resolveProfile(ref){const values=[ref];if(state.user){values.push(authUserId(state.user),state.user.profile_id,state.user.slug);}for(const value of [...new Set(values.filter(Boolean).map(x=>String(x).trim()))]){try{const profile=await service.getProfile(value);if(profile)return profile;}catch(error){console.warn('[DanaTrap profile lookup]',value,error);}}return null;}
function productionImage(source){return source?.coverImage||source?.cover_image||source?.payload?.cover_image||'';}
function productionCoverStyle(source,fit='cover'){const image=productionImage(source);const version=source?.updated_at||source?.payload?.cover_version||source?.payload?.drive_id||'';return imageBackground(image,version,fit,source?.design?.coverPosition||'center');}
function safeFontName(name){return String(name||'Inter').replace(/[^a-zA-Z0-9À-ÿ _-]/g,'').trim()||'Inter';}
function cssFontFamily(name){return `"${safeFontName(name)}",Inter,Manrope,system-ui,sans-serif`;}
function fontCatalog(){const builtins=['Inter','Space Grotesk','Manrope','Montserrat','Playfair Display','Bebas Neue'];const custom=Array.isArray(window.DRSX_FONTS)?window.DRSX_FONTS.map(x=>typeof x==='string'?x:x?.family).filter(Boolean):[];return [...new Set([...builtins,...custom])];}
function fontOptions(current='Inter'){return fontCatalog().map(name=>`<option value="${esc(name)}" ${selected(name,current)}>${esc(name)}</option>`).join('');}
function detailSurface(design={}){const mode=design.detailBackgroundMode||'gradient',solid=design.detailBackground||design.background||'#101114',start=design.detailGradientStart||design.background||'#101114',end=design.detailGradientEnd||design.secondary||'#343b55',angle=Number(design.detailGradientAngle??135);if(mode==='solid')return solid;if(mode==='image')return solid;return `linear-gradient(${angle}deg,${start},${end})`;}
function productionDetailVars(beat={}){const d=beat.design||{},image=mediaUrl(d.detailBackgroundImage,d.detailBackgroundVersion||beat.updated_at||'');return `--detail-surface:${detailSurface(d)};--detail-bg-image:${image?`url('${esc(image)}')`:'none'};--detail-bg-fit:${d.detailBackgroundFit||'cover'};--detail-bg-position:${d.detailBackgroundPosition||'center'};--detail-bg-zoom:${Math.max(80,Math.min(220,Number(d.detailBackgroundZoom??100)))/100};--detail-bg-blur:${Math.max(0,Math.min(30,Number(d.detailBackgroundBlur??0)))}px;--detail-bg-overlay:${Math.max(0,Math.min(95,Number(d.detailBackgroundOverlay??38)))/100};--detail-font:${cssFontFamily(d.titleFont||'Inter')}`;}
function waveformPlayerMarkup(beat){return `<div class="wave-player" data-detail-waveform="${esc(beat.id)}"><div class="wave-main"><button class="wave-play" type="button" data-wave-toggle="${esc(beat.id)}" aria-label="Lecture ou pause">${state.current?.id===beat.id&&state.isPlaying?pauseIcon(beat):playIcon(beat)}</button><div class="wave-scroll" data-wave-scroll><div class="wave-stage" data-wave-stage><canvas data-wave-canvas-base aria-label="Forme d’onde interactive"></canvas><canvas data-wave-canvas-played aria-hidden="true"></canvas><div class="wave-progress" data-wave-progress></div><div class="wave-selection" data-wave-selection><i data-wave-selection-start></i><i data-wave-selection-end></i></div><div class="wave-cursor" data-wave-cursor></div></div></div></div><div class="wave-controls"><span data-wave-current>0:00.000</span><button type="button" class="btn subtle small" data-wave-loop disabled>Boucle désactivée</button><button type="button" class="btn subtle small" data-wave-clear disabled>Effacer la sélection</button><label>Zoom<input type="range" min="1" max="8" step="1" value="1" data-wave-zoom></label><span data-wave-duration>${esc(beat.duration||'0:00')}</span></div><p class="wave-help">Clique pour te déplacer. Glisse pour sélectionner une boucle précisément calée sur la forme d’onde.</p></div>`;}
function productionDetailPreviewMarkup(beat){const d=beat.design||{};return `<div class="production-detail-mini mode-${esc(d.detailBackgroundMode||'gradient')}" style="${productionDetailVars(beat)}"><div class="production-detail-background"></div><div class="production-detail-mini-grid"><span class="mini-detail-cover" style="${productionCoverStyle(beat)}"></span><div><span class="eyebrow">${esc(beat.genre||'Genre')} · ${esc(beat.mood||'Ambiance')}</span><h3 style="font-family:${cssFontFamily(d.titleFont||'Inter')}">${esc(beat.title||'Titre de la production')}</h3><div class="mini-wave-preview">${wave(24)}</div><small>${esc(beat.bpm||140)} BPM · ${esc(beat.key||'C min')}</small></div></div></div>`;}
function countdownLabel(expiresAt){if(!expiresAt)return'';const diff=new Date(expiresAt).getTime()-Date.now();if(diff<=0)return'Expiration en cours';const total=Math.floor(diff/1000),d=Math.floor(total/86400),h=Math.floor((total%86400)/3600),m=Math.floor((total%3600)/60);return d?`${d} j ${h} h restantes`:`${h} h ${m} min restantes`;}
function activateCountdowns(){clearInterval(state.countdownTimer);const update=()=>document.querySelectorAll('[data-expires-at]').forEach(el=>{el.textContent=countdownLabel(el.dataset.expiresAt);});update();if(document.querySelector('[data-expires-at]'))state.countdownTimer=setInterval(update,30000);}
function themeSurface(theme={}){
 const mode=theme.backgroundMode||'gradient',solid=theme.background||'#111217',start=theme.gradientStart||theme.background||'#111217',end=theme.gradientEnd||theme.secondary||'#7c5cff',angle=Number(theme.gradientAngle??145);
 if(mode==='solid')return solid;
 if(mode==='image')return `linear-gradient(rgba(5,6,8,${Math.max(0,Math.min(95,Number(theme.backgroundOverlay??35)))/100}),rgba(5,6,8,${Math.max(0,Math.min(95,Number(theme.backgroundOverlay??35)))/100})), ${solid}`;
 return `linear-gradient(${angle}deg,${start},${end})`;
}
function themeVars(theme={}){const image=mediaUrl(theme.backgroundImage,theme.backgroundVersion||'');return `--profile-accent:${theme.accent||'#f6c90e'};--profile-secondary:${theme.secondary||'#7c5cff'};--profile-bg:${theme.background||'#111217'};--profile-gradient-start:${theme.gradientStart||theme.background||'#111217'};--profile-gradient-end:${theme.gradientEnd||theme.secondary||'#7c5cff'};--profile-gradient-angle:${Number(theme.gradientAngle??145)}deg;--profile-surface:${themeSurface(theme)};--profile-bg-image:${image?`url('${esc(image)}')`:'none'};--profile-bg-opacity:${Math.max(0,Math.min(100,Number(theme.backgroundImageOpacity??75)))/100};--profile-bg-overlay:${Math.max(0,Math.min(95,Number(theme.backgroundOverlay??35)))/100};--profile-radius:${Number(theme.cardRadius)||24}px;--profile-border:${theme.cardBorder||'rgba(255,255,255,.13)'};--identity-bg:${theme.identityBackground||'rgba(14,15,20,.82)'};--identity-alpha:${Math.max(20,Math.min(100,Number(theme.identityOpacity??86)))}%;--identity-align:${theme.identityAlign||'left'};--profile-font:${cssFontFamily(theme.fontFamily||'Inter')}`;}
function coverStyle(b){const d=b.design||{};const image=productionImage(b);const overlay=Math.max(0,Math.min(90,Number(d.overlay??45)))/100;const img=image?`background-image:linear-gradient(rgba(0,0,0,${overlay}),rgba(0,0,0,${overlay})),url('${esc(mediaUrl(image,b.updated_at||''))}');background-size:cover;background-position:${esc(d.coverPosition||'center')};`:'';return `${themeVars(d)};${img};font-family:${cssFontFamily(d.titleFont||'Inter')}`;}
function playIcon(b){return b?.design?.customPlayIcon?`<img src="${esc(b.design.customPlayIcon)}" alt="">`:icon('play');}
function pauseIcon(b){return b?.design?.customPauseIcon?`<img src="${esc(b.design.customPauseIcon)}" alt="">`:icon('pause');}
function canEditBeat(b){return state.user&&(isAdmin()||state.user.id===b.producer_id);}
function isCreator(){return Boolean(state.user&&hasRole('Beatmaker'));}
function canInvoice(){return Boolean(state.user&&(isAdmin()||hasRole('Beatmaker')||hasRole('Producteur')||hasRole('Manager')));}
function isArtist(){return Boolean(state.user&&hasRole('Artiste'));}
function apiBase(){return String(window.DRSX_CONFIG?.apiBaseUrl||window.DRSX_CONFIG?.driveWorkerUrl||'').replace(/\/$/,'');}
function previewFile(beat){return (beat?.files||[]).find(file=>file?.kind==='preview'&&file?.drive_id)||(beat?.files||[]).find(file=>file?.kind==='preview');}
function mediaSourceForBeat(beat){
 const file=previewFile(beat),api=apiBase();
 if(!window.DRSXData.isDemo()&&api&&file?.drive_id)return `${api}/public-media/${encodeURIComponent(file.drive_id)}`;
 return beat?.audio||file?.stream_url||beat?.preview_url||'';
}
function audioErrorText(){
 const code=audio.error?.code||0;
 if(code===1)return 'La lecture a été interrompue.';
 if(code===2)return 'Le fichier audio n’a pas pu être chargé depuis le serveur.';
 if(code===3)return 'Le navigateur ne parvient pas à décoder cette préécoute.';
 if(code===4)return 'Format audio non pris en charge. Utilise une préécoute MP3 ou WAV standard.';
 return 'Impossible de lire cette préécoute.';
}
function validatePreviewFile(file){
 if(!file)return Promise.resolve(null);
 const supported=/\.(mp3|wav)$/i.test(file.name)||['audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/wave'].includes(String(file.type||'').toLowerCase());
 if(!supported)return Promise.reject(new Error('La préécoute doit être un fichier MP3 ou WAV standard.'));
 return new Promise((resolve,reject)=>{
  const probe=document.createElement('audio'),url=URL.createObjectURL(file),timer=setTimeout(()=>done(new Error('Impossible de lire les informations de cette préécoute.')),15000);
  const done=(error,value)=>{clearTimeout(timer);probe.removeAttribute('src');probe.load();URL.revokeObjectURL(url);error?reject(error):resolve(value);};
  probe.preload='metadata';probe.onloadedmetadata=()=>done(null,Number.isFinite(probe.duration)?probe.duration:null);probe.onerror=()=>done(new Error('Cette préécoute ne peut pas être décodée. Exporte-la en MP3 320 kb/s ou WAV PCM.'));probe.src=url;
 });
}

function beatCard(b,{owner=false,publicView=false}={}){
 const expired=b.visibility==='Expiré',isOwn=Boolean(state.user&&state.user.id===b.producer_id);
 const actions=publicView?(isOwn?`<a class="btn subtle small" href="#/beat/${b.slug||b.id}">Voir</a>`:expired?'':`<a class="btn primary small" href="#/beat/${b.slug||b.id}">${icon('reserve')} Réserver</a>`):(owner||canEditBeat(b)?`<a class="btn subtle small" href="#/app/production/${b.id}/edit">${icon('edit')} Modifier</a>`:expired?'':`<a class="btn primary small" href="#/beat/${b.slug||b.id}">${icon('reserve')} Réserver</a>`);
 return `<article class="beat-card custom-beat-card ${expired?'expired':''}" style="${coverStyle(b)}">
  <div class="beat-cover ${b.coverClass||'cover-a'}" style="${productionCoverStyle(b)}">
   <span class="cover-grid"></span><span class="status beat-status ${statusClass(b.visibility)}">${esc(b.visibility)}</span>
   <button class="beat-play" data-play="${b.id}" aria-label="Lire ${esc(b.title)}">${state.current?.id===b.id&&state.isPlaying?pauseIcon(b):playIcon(b)}</button><span class="beat-duration">${esc(b.duration||'0:00')}</span>
  </div>
  <div class="beat-card-body ${esc(b.design?.infoLayout||'bottom')}"><div class="beat-title-row"><div><a class="beat-title" href="#/beat/${b.slug||b.id}">${esc(b.title)}</a><a class="producer-link" href="#/profile/${b.producer_slug||b.producer_id}">${esc(b.producer_name)}</a></div><button class="icon-btn" data-menu-beat="${b.id}">${icon('more')}</button></div>
  <div class="chips"><span>${esc(b.bpm)} BPM</span><span>${esc(b.key)}</span><span>${esc(b.genre)}</span></div>
  <div class="beat-foot"><span>${icon('headphones')} ${fmt(b.plays)}</span><div class="card-actions">${actions}</div></div></div>
 </article>`;
}
function beatGrid(list,opts={}){return list.length?`<div class="beats-grid">${list.map(b=>beatCard(b,opts)).join('')}</div>`:`<div class="empty-state"><span>${icon('music')}</span><strong>Aucune production</strong><p>Aucun résultat ne correspond à cette sélection.</p></div>`;}
function profileCard(p){const t=p.theme||{},roles=[p.is_admin?'Admin':'',...(p.roles||[p.role]).filter(r=>r&&r!=='Admin')].filter(Boolean);return `<article class="creator-card theme-frame ${esc(t.frameStyle||'glass')}" style="${themeVars(t)}"><div class="creator-banner profile-effect ${esc(t.profileEffect||'none')}" style="${imageBackground(p.banner,p.updated_at)}"></div><div class="creator-card-main">${profileAvatar(p,'large')}<div><a href="#/profile/${p.slug||p.user_id}"><strong>${esc(p.name)} ${p.verified?'<span class="verified">✓</span>':''}</strong></a><span>${esc(roles.join(' · ')||'Membre')} · ${esc(p.location||'Non renseigné')}</span></div></div><p>${esc(p.bio||'Aucune biographie renseignée.')}</p><div class="creator-stats"><span><strong>${fmt(p.followers)}</strong> abonnés</span><span><strong>${fmt(p.plays)}</strong> écoutes</span></div><a class="btn profile-btn" href="#/profile/${p.slug||p.user_id}">Voir le profil ${icon('arrow')}</a></article>`;}
