function landing(beats,makers,artists){return `<div class="landing"><header class="landing-nav">${logo()}<nav><a href="#beats">Productions</a><a href="#creators">Créateurs</a><a href="#how">Réservation</a></nav><div class="landing-actions"><a class="btn subtle" href="#/connexion">Connexion</a><a class="btn primary" href="#/inscription">Créer un compte</a></div></header><main><section class="hero"><span class="cover-grid"></span><div class="hero-copy"><span class="badge">✦ Une identité différente pour chaque créateur</span><h1>Réserve. Discute.<br><em>Crée ton morceau.</em></h1><p>Découvre une production, choisis une licence et ouvre automatiquement une conversation privée avec le beatmaker. Aucun paiement imposé : les deux créateurs décident ensemble.</p><div class="hero-actions"><a class="btn primary" href="#/explorer">Explorer les productions ${icon('arrow')}</a><a class="btn ghost" href="#/inscription">Créer mon univers</a></div><div class="hero-metrics"><div><strong>${makers.length}+</strong><span>${window.DRSXData.isDemo()?'Beatmakers démo':'Beatmakers'}</span></div><div><strong>${artists.length}+</strong><span>${window.DRSXData.isDemo()?'Artistes démo':'Artistes'}</span></div><div><strong>100%</strong><span>Réservation et discussion</span></div></div></div><div class="hero-visual"><span class="hero-orb"></span><div class="hero-card"><div class="hero-cover cover-a"><span class="cover-grid"></span><span class="floating-tag">Sélection RSX</span><button class="hero-play" data-play="${beats[0]?.id||''}">${playIcon(beats[0])}</button></div><div class="hero-card-info"><span class="eyebrow">Production mise en avant</span><h3>${esc(beats[0]?.title||'Nocturne')}</h3><p>${esc(beats[0]?.producer_name||'Dzl 971')} · ${esc(beats[0]?.bpm||142)} BPM · ${esc(beats[0]?.key||'B min')}</p><div class="waveform">${wave()}</div></div></div></div></section><section id="beats" class="landing-section"><div class="center-title"><span class="badge">Catalogue</span><h2>Des productions avec une vraie identité</h2><p>Chaque beatmaker peut personnaliser ses cartes, ses licences, ses boutons et son univers visuel.</p></div>${beatGrid(beats.slice(0,4))}</section><section id="how" class="landing-section feature-wrap"><div class="center-title"><span class="badge">Nouveau fonctionnement</span><h2>La réservation remplace le paiement direct</h2></div><div class="feature-grid">${[['◇','Choix de la licence','L’artiste sélectionne MP3, WAV, Premium, Exclusive ou une licence personnalisée.'],['◫','Conversation automatique','Une discussion privée est créée avec un bloc complet sur la production réservée.'],['✓','Décision entre créateurs','Le beatmaker accepte, refuse ou négocie, puis marque la production Expirée si elle est prise.'],['✦','Profils uniques','Couleurs, effets, cadres, arrière-plan, réseaux, polices et icônes personnalisées.'],['△','Stockage Drive','MP3, WAV, FLP, ZIP, stems et images sont envoyés vers ton Google Drive.'],['♛','Administration totale','Dzl 971 peut modifier, ajouter, retirer ou supprimer tous les contenus et comptes.']].map(x=>`<article class="feature-card"><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section id="creators" class="landing-section"><div class="center-title"><span class="badge">Communauté</span><h2>Beatmakers et artistes à découvrir</h2></div>${profileGrid([...makers.slice(0,2),...artists.slice(0,2)])}</section><section class="landing-section"><div class="cta"><div><span class="badge">DanaTrap RSX</span><h2>Construis une page qu’on reconnaît immédiatement.</h2><p>Ton profil, tes productions, tes effets et tes propres icônes.</p></div><a class="btn primary" href="#/inscription">Commencer gratuitement ${icon('arrow')}</a></div></section></main><footer class="landing-footer">${logo()}<p>© 2026 DanaTrap RSX — Réservation et collaboration musicale.</p></footer></div>`;}

function authPage(mode='login'){
 const login=mode==='login',demo=window.DRSXData.isDemo();
 const demoBox=demo?`<div class="demo-box"><strong>Comptes de démonstration</strong><span>Beatmaker : demo@danatrap.fr / DEMO1234</span><span>Artiste : artiste@danatrap.fr / ARTISTE1234</span><span>Administrateur Dzl 971 : admin@danatrap.fr / ADMIN1234</span></div>`:'';
 return `<div class="auth-page"><section class="auth-art"><div>${logo()}</div><div class="auth-quote"><span class="badge">DanaTrap RSX</span><blockquote>${login?'Retrouve tes réservations et tes conversations.':'Crée ton espace, puis personnalise-le sans limite.'}</blockquote><p>${demo?'Le site fonctionne actuellement en mode démonstration local.':'Tes comptes, réservations et conversations sont connectés à la plateforme en ligne.'}</p></div><small>Réservation · Messagerie · Drive · Personnalisation</small></section><section class="auth-panel"><a class="back-link" href="#/">← Retour à l’accueil</a><div class="auth-box"><h1>${login?esc((state.siteAppearance||DEFAULT_SITE_APPEARANCE).loginTitle):'Créer mon compte'}</h1><p>${login?esc((state.siteAppearance||DEFAULT_SITE_APPEARANCE).loginSubtitle):'Choisis ton rôle. Tu pourras modifier ton profil ensuite.'}</p><form id="${login?'login':'register'}-form" class="form">${login?'':`<label>Nom public<input name="name" required placeholder="Ton nom d’artiste"></label><label>Rôle<select name="role" required><option>Artiste</option><option>Beatmaker</option><option>Producteur</option><option>Ingénieur du son</option><option>Manager</option></select></label>`}<label>Adresse e-mail<input type="email" name="email" required value="${login&&demo?'demo@danatrap.fr':''}"></label><label>Mot de passe<input type="password" name="password" required minlength="8" value="${login&&demo?'DEMO1234':''}"></label>${login?'<div class="auth-help-row"><a href="#/mot-de-passe-oublie">Mot de passe oublié ?</a></div><p id="login-error" class="form-error hidden"></p>':''}<button class="btn primary full" type="submit">${login?'Se connecter':'Créer mon compte'}</button>${demoBox}</form><p class="auth-switch">${login?'Pas encore de compte ? <a href="#/inscription">Inscription</a>':'Déjà inscrit ? <a href="#/connexion">Connexion</a>'}</p></div></section></div>`;
}

function renderModal(){const m=state.modal;if(!m)return'';if(m.type==='reserve')return `<div class="modal-backdrop"><div class="modal-card"><button class="modal-close" data-close-modal>×</button><span class="badge">Réservation</span><h2>${esc(m.beat.title)}</h2><p>Licence choisie : <strong>${esc(m.license)}</strong></p><div class="reservation-mini"><span class="mini-cover ${m.beat.coverClass||'cover-a'}"></span><div><strong>${esc(m.beat.title)}</strong><span>${esc(m.beat.producer_name)} · ${m.beat.bpm} BPM · ${esc(m.beat.key)}</span></div></div><label>Message facultatif<textarea id="reservation-note" placeholder="Présente ton projet ou demande une modification..."></textarea></label><p class="modal-note">Après confirmation, le beatmaker reçoit une notification et une conversation est créée automatiquement.</p><button class="btn primary full" data-confirm-reservation>Confirmer la réservation</button></div></div>`;if(m.type==='announcement')return `<div class="modal-backdrop"><form id="announcement-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><h2>Publier une annonce</h2><label>Titre<input name="title" required></label><label>Besoin<textarea name="details" required></textarea></label><label>Budget indicatif<input name="budget" required placeholder="80–130 €"></label><label>Date limite<input name="deadline" required placeholder="31 août 2026"></label><button class="btn primary">Publier</button></form></div>`;if(m.type==='playlist')return `<div class="modal-backdrop"><form id="playlist-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><h2>Nouvelle playlist</h2><label>Nom<input name="name" required placeholder="Ex. Projet album"></label><button class="btn primary">Créer</button></form></div>`;if(m.type==='addUser')return `<div class="modal-backdrop"><form id="admin-add-user-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><h2>Ajouter un utilisateur</h2><label>Nom<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Mot de passe<input name="password" value="DEMO1234" required></label><label>Rôle<select name="role"><option>Artiste</option><option>Beatmaker</option><option>Manager</option></select></label><button class="btn primary">Ajouter</button></form></div>`;if(m.type==='report')return `<div class="modal-backdrop"><form id="report-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><span class="badge">Signalement</span><h2>Signaler ce contenu</h2><label>Motif<select name="reason"><option>Contenu trompeur</option><option>Harcèlement ou spam</option><option>Contenu inapproprié</option><option>Violation de droits</option><option>Autre</option></select></label><label>Détails<textarea name="details" required placeholder="Explique clairement le problème..."></textarea></label><button class="btn danger-btn" type="submit">Envoyer le signalement</button></form></div>`;if(m.type==='verification')return `<div class="modal-backdrop"><form id="verification-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><span class="badge">Certification</span><h2>Demander le badge Vérifié</h2><label>Présente ton activité<textarea name="message" required placeholder="Réseaux, activité, projets, raisons de la demande..."></textarea></label><button class="btn primary" type="submit">Envoyer la demande</button></form></div>`;if(m.type==='beatMenu'){const editable=canEditBeat(m.beat);return `<div class="modal-backdrop beat-menu-backdrop"><div class="modal-card beat-menu-card"><button class="modal-close" data-close-modal>×</button><div class="beat-menu-preview"><span class="mini-cover" style="${productionCoverStyle(m.beat)}"></span><div><span class="eyebrow">Production</span><h2>${esc(m.beat.title)}</h2><p>${esc(m.beat.producer_name)} · ${esc(m.beat.bpm)} BPM · ${esc(m.beat.key)}</p></div></div><div class="beat-menu-actions"><a class="btn subtle full" href="#/beat/${m.beat.slug||m.beat.id}">Voir la production</a>${editable?`<a class="btn primary full" href="#/app/production/${m.beat.id}/edit">Modifier</a><button class="btn danger-btn full" data-delete-beat="${m.beat.id}">Supprimer la production</button>`:''}</div></div></div>`;}return'';}

function loading(){return `<div class="loading-screen"><div class="loading-bars">${Array.from({length:7},(_,i)=>`<i style="height:${18+(i%4)*8}px"></i>`).join('')}</div><p>Chargement de DanaTrap RSX…</p></div>`;}
function notFound(){return state.user?appShell('Page introuvable','La route demandée n’existe pas.',`<div class="empty-state full-page"><strong>404</strong><p>Cette page n’existe pas ou a été déplacée.</p><a class="btn primary" href="#/app">Retour au tableau de bord</a></div>`):`<div class="empty-state full-page"><strong>404</strong><p>Cette page n’existe pas.</p><a class="btn primary" href="#/">Retour à l’accueil</a></div>`;}
function activeRoute(path){const raw=(location.hash||'#/app').slice(1);return path==='/app'?raw==='/app':raw===path||raw.startsWith(path+'/');}
function navItem(path,label,i){return `<a class="side-link ${activeRoute(path)?'active':''}" href="#${path}"><span>${icon(i)}</span>${esc(label)}</a>`;}
function mobileItem(path,label,i){return `<a class="${activeRoute(path)?'active':''}" href="#${path}"><span>${icon(i)}</span><small>${esc(label)}</small></a>`;}
function playerMarkup(){const b=state.current;if(!b)return `<div class="player player-empty"><span>${icon('music')}</span><p>Sélectionne une production pour lancer la préécoute.</p></div>`;return `<div class="player ${state.isPlaying?'is-playing':''}"><div class="player-track"><span class="mini-cover ${b.coverClass||'cover-a'}" style="${productionCoverStyle(b)}"></span><div><strong>${esc(b.title)}</strong><span>${esc(b.producer_name)}</span></div></div><div class="player-center"><div class="player-controls"><button data-player="prev" aria-label="Précédent">${icon('prev')}</button><button class="player-toggle" data-player="toggle" aria-label="Lecture pause">${state.isPlaying?pauseIcon(b):playIcon(b)}</button><button data-player="next" aria-label="Suivant">${icon('next')}</button></div><div class="progress-row"><small id="current-time">0:00</small><input id="progress" type="range" min="0" max="100" value="0"><small id="duration">${esc(b.duration||'0:00')}</small></div></div><div class="player-extra"><button class="icon-btn" data-favorite="${b.id}">${icon('heart')}</button><span>${icon('headphones')}</span><input id="volume" class="volume" type="range" min="0" max="1" step=".05" value="${audio.volume||.75}"></div></div>`;}
function appShell(title,subtitle,content){const unread=(state.notifications||[]).filter(n=>!n.read).length;const creator=isCreator();const nav=(key,html)=>flagEnabled(key)?html:'';return `<div class="app-shell">${state.viewAsRole?`<div class="view-as-banner">Aperçu administrateur : ${esc(state.viewAsRole)} <button data-exit-view-as>Quitter l’aperçu</button></div>`:''}<aside class="sidebar">${logo()}<nav class="side-nav">${navItem('/app','Tableau de bord','home')}${nav('reservations',navItem('/app/explorer','Explorer','explore'))}${nav('activity_feed',navItem('/app/abonnements','Abonnements','feed'))}${navItem('/app/beatmakers','Beatmakers','users')}${navItem('/app/artistes','Artistes','artist')}${navItem('/app/favoris','Favoris','heart')}${navItem('/app/playlists','Playlists','library')}${nav('messaging',navItem('/app/messages','Messages','message'))}${nav('reservations',navItem('/app/reservations','Réservations','reserve'))}${canInvoice()?navItem('/app/factures','Factures','invoice'):''}${nav('collaborations',navItem('/app/collaborations','Collaborations','users'))}${nav('announcements',navItem('/app/annonces','Annonces','announce'))}${creator&&flagEnabled('uploads')?navItem('/app/productions','Mes productions','music'):''}${navItem('/app/personnalisation','Personnalisation','palette')}${navItem('/app/statistiques','Statistiques','stats')}${isAdmin()?navItem('/admin','Administration','admin'):''}${isAdmin()?navItem('/admin/aspect','Aspect','palette'):''}</nav><div class="side-bottom">${navItem('/app/parametres/compte','Paramètres','settings')}<button class="side-link" data-action="logout"><span>↪</span>Déconnexion</button></div></aside><header class="topbar"><div><span class="eyebrow">${esc(subtitle||'DanaTrap RSX')}</span><h1>${esc(title)}</h1></div><div class="top-actions"><a class="icon-btn notification-btn ${unread?'unread':''}" href="#/app/notifications" aria-label="Notifications">${icon('bell')}${unread?`<small>${unread}</small>`:''}</a><a class="user-pill" href="#/profile/${authUserId(state.user)}">${profileAvatar(state.user,'small')}<div><strong>${esc(state.user?.name||'Compte')}</strong><small>${esc(rolesLabel(state.user))}</small></div></a></div></header><main class="page-wrap">${content}</main>${playerMarkup()}<nav class="mobile-nav">${mobileItem('/app','Accueil','home')}${mobileItem('/app/explorer','Explorer','explore')}${mobileItem('/app/abonnements','Suivis','feed')}${mobileItem('/app/messages','Messages','message')}${mobileItem('/app/personnalisation','Profil','palette')}</nav>${renderModal()}</div>`;}
function publicShell(content){return `<div class="landing"><header class="landing-nav">${logo()}<nav><a href="#/explorer">Productions</a><a href="#/connexion">Connexion</a></nav><div class="landing-actions"><a class="btn subtle" href="#/connexion">Connexion</a><a class="btn primary" href="#/inscription">Créer un compte</a></div></header><main class="landing-section">${content}</main><footer class="public-legal-links"><a href="#/legal/terms">Conditions</a><a href="#/legal/privacy">Confidentialité</a><a href="#/legal/community">Règles</a></footer>${playerMarkup()}</div>${renderModal()}`;}
function profileById(list,id){return list.find(p=>p.user_id===id)||{name:'Utilisateur',initials:'UT',role:'Membre'};}
function selected(v,current){return String(v)===String(current)?'selected':'';}
function checked(v){return v?'checked':'';}

async function dashboard(){
 const [profile,reservations,conversations,announcementsList,collabs,recommended,followFeed]=await Promise.all([
  resolveProfile(authUserId(state.user)),service.listReservations(state.user),service.listConversations(state.user),service.announcements(),service.collaborations(state.user),service.recommendedBeats(state.user,8),service.activityFeed(state.user,8)
 ]);
 const ownBeats=isCreator()?await service.listBeats({producer_id:authUserId(state.user)}):[];
 const pending=reservations.filter(r=>!['Acceptée','Refusée','Annulée','Expirée'].includes(r.status)).length,unread=(state.notifications||[]).filter(n=>!n.read).length;
 const primaryRole=rolesOf(state.user)[0]||state.user.role||'Membre';
 const heroTitle=primaryRole==='Artiste'?'Une sélection construite autour de ton univers.':isCreator()?'Pilote ton catalogue et découvre les artistes qui te suivent.':'Retrouve toute ton activité musicale.';
 const heroText=primaryRole==='Artiste'?'Tes genres, BPM, favoris et créateurs suivis améliorent automatiquement les recommandations.':'Nouvelles réservations, activité des profils suivis et performances de tes productions.';
 const onboarding=!onboardingComplete(profile)?`<section class="onboarding-banner"><div><span class="badge">${icon('welcome')} Première configuration</span><h3>Personnalise ton expérience DanaTrap RSX.</h3><p>Choisis tes genres, ton BPM préféré et complète ton profil pour obtenir de meilleures recommandations.</p></div><a class="btn primary" href="#/app/bienvenue">Commencer</a></section>`:'';
 const recommendationSection=flagEnabled('recommendations')?`<section>${sectionTitle('Pour toi','Productions classées selon tes préférences, favoris et abonnements.',`<a class="text-link" href="#/app/explorer">Explorer tout →</a>`)}${beatGrid(recommended.slice(0,4))}</section>`:'';
 const followedSection=flagEnabled('activity_feed')?`<section>${sectionTitle('Nouveautés des créateurs suivis','Les dernières productions des profils auxquels tu es abonné.',`<a class="text-link" href="#/app/abonnements">Voir le fil →</a>`)}${followFeed.length?beatGrid(followFeed.slice(0,4).map(x=>x.beat)):'<div class="empty-state"><strong>Ton fil est encore vide</strong><p>Suis des beatmakers et artistes pour voir leur activité ici.</p><a class="btn subtle" href="#/app/beatmakers">Découvrir des beatmakers</a></div>'}</section>`:'';
 const ownSection=isCreator()?`<section>${sectionTitle('Tes productions récentes','Accès rapide à ton catalogue.',`<a class="text-link" href="#/app/productions">Tout afficher →</a>`)}${beatGrid(ownBeats.slice(0,4),{owner:true})}</section>`:'';
 const body=`<div class="stack">${onboarding}<section class="dashboard-hero"><div><span class="badge">Bonjour ${esc(profile?.name||state.user.name)}</span><h2>${esc(heroTitle)}</h2><p>${esc(heroText)}</p><div class="hero-actions">${isCreator()?'<a class="btn primary" href="#/app/upload">Ajouter une production</a>':'<a class="btn primary" href="#/app/explorer">Explorer les productions</a>'}<a class="btn ghost" href="#/app/abonnements">Mon fil d’abonnements</a></div></div><div class="disc"><span>DRSX</span></div></section><section class="stats-grid">${statCard('headphones','Écoutes',fmt(profile?.plays||0),'Activité totale')}${statCard('reserve','Réservations',String(reservations.length),`${pending} en cours`)}${statCard('message','Conversations',String(conversations.length),`${unread} notification(s)`)}${statCard('users','Collaborations',String(collabs.length),'Projets privés')}</section>${ownSection}${recommendationSection}${followedSection}<div class="two-columns"><section class="panel">${sectionTitle('Dernières conversations','Tes échanges les plus récents.',`<a class="text-link" href="#/app/messages">Messages →</a>`)}${conversations.length?conversations.slice(0,4).map(c=>`<a class="project-row" href="#/app/messages/${c.id}">${profileAvatar((c.members_profiles||[]).find(p=>p.user_id!==state.user.id)||c.members_profiles?.[0],'small')}<div class="project-info"><strong>${esc(c.title)}</strong><span>${esc(c.last_message?.text||'Aucun message')}</span></div><div class="project-meta"><strong>${timeAgo(c.updated_at)}</strong><small>Ouvrir</small></div></a>`).join(''):'<div class="empty-state"><strong>Aucune conversation</strong></div>'}</section><section class="panel">${sectionTitle('Annonces récentes','Besoins publiés par la communauté.',`<a class="text-link" href="#/app/annonces">Voir tout →</a>`)}${announcementsList.slice(0,4).map(a=>`<div class="announcement-row"><span class="avatar small">${initials(a.author)}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.details)}</p><small>${esc(a.budget)} · ${esc(a.deadline)}</small></div></div>`).join('')}</section></div></div>`;
 updateSeo({title:'Tableau de bord',description:'Ton espace personnalisé DanaTrap RSX.'});
 return appShell('Tableau de bord','Accueil personnalisé',body);
}

async function explore(publicView=false){const genres=['Tous','Trap','Drill','Afro','R&B','Dancehall','Pop urbaine'];const beats=await service.listBeats({publicOnly:true,genre:state.genre,query:state.query});const content=`<div class="stack"><section class="explore-hero"><div><span class="badge">Catalogue DanaTrap</span><h2>Explore les univers des beatmakers.</h2><p>Écoute les préversions, compare les licences puis réserve la production qui correspond à ton projet.</p></div><label class="search-box">${icon('search')}<input id="beat-search" value="${esc(state.query)}" placeholder="Titre, beatmaker, genre…"></label></section><section class="filters"><div class="genre-tabs">${genres.map(g=>`<button class="${state.genre===g?'active':''}" data-genre="${esc(g)}">${esc(g)}</button>`).join('')}</div><div class="filter-grid"><label>Humeur<select><option>Toutes</option><option>Sombre</option><option>Énergique</option><option>Mélancolique</option></select></label><label>BPM<select><option>Tous</option><option>80–110</option><option>111–140</option><option>141+</option></select></label><label>Licence<select><option>Toutes</option><option>MP3</option><option>WAV</option><option>Premium</option><option>Exclusive</option></select></label><label>Disponibilité<select><option>Publié et réservé</option><option>Publié uniquement</option></select></label></div></section><section>${sectionTitle(`${beats.length} production${beats.length>1?'s':''}`,'Résultats disponibles dans le catalogue.')}${beatGrid(beats)}</section></div>`;return publicView?publicShell(content):appShell('Explorer','Catalogue des productions',content);}

async function beatDetail(ref,{privatePreview=false}={}){
 const beat=await service.getBeat(ref);if(!beat)return notFound();
 if(privatePreview&&(!state.user||!canEditBeat(beat)))return notFound();
 if(!privatePreview&&beat.visibility==='Brouillon'&&(!state.user||!canEditBeat(beat)))return notFound();
 const producer=await service.getProfile(beat.producer_id);updateSeo({title:beat.title,description:beat.description||`${beat.genre} · ${beat.bpm} BPM par ${beat.producer_name}`,image:mediaUrl(beat.coverImage||'',beat.updated_at||''),url:location.href,type:'music.song'});const licenses=(beat.licenses||[]).filter(l=>l.active!==false),available=beat.visibility!=='Expiré'&&beat.visibility!=='Brouillon',d=beat.design||{};
 const body=`<div class="detail-page custom-detail mode-${esc(d.detailBackgroundMode||'gradient')}" style="${coverStyle(beat)};${productionDetailVars(beat)}"><div class="production-detail-background"></div>${privatePreview?'<div class="private-preview-banner">Aperçu privé — cette production n’est pas visible publiquement.</div>':''}<a class="detail-back btn subtle small" href="${privatePreview?'#/app/productions':state.user?'#/app/explorer':'#/explorer'}">← Retour</a><section class="detail-hero"><div class="detail-cover ${beat.coverClass||'cover-a'}" style="${productionCoverStyle(beat)}"><span class="cover-grid"></span><span class="status beat-status ${statusClass(beat.visibility)}">${esc(beat.visibility)}</span></div><div class="detail-info"><span class="eyebrow">${esc(beat.genre)} · ${esc(beat.mood)}</span><h2 style="font-family:${cssFontFamily(d.titleFont||'Inter')}">${esc(beat.title)}</h2><a class="producer-line" href="#/profile/${producer?.slug||beat.producer_id}">${profileAvatar(producer,'small')}<div><strong>${esc(beat.producer_name)}</strong><small>${esc(rolesLabel(producer))} · ${esc(producer?.location||'')}</small></div></a><p>${esc(beat.description||'Aucune description renseignée.')}</p><div class="chips detail-chips"><span>${beat.bpm} BPM</span><span>${esc(beat.key)}</span>${(beat.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${waveformPlayerMarkup(beat)}<div class="detail-actions"><button class="btn subtle" data-favorite="${beat.id}">${icon('heart')} Favori</button><button class="btn subtle" data-share-title="${esc(beat.title)}" data-share-text="${esc(`${beat.genre} · ${beat.bpm} BPM par ${beat.producer_name}`)}">${icon('share')} Partager</button>${canEditBeat(beat)?`<a class="btn primary" href="#/app/production/${beat.id}/edit">Modifier la production</a>`:state.user?`<button class="btn subtle" data-report-type="beat" data-report-id="${beat.id}">Signaler</button>`:''}</div></div></section>${rightsSummary(beat)}${privatePreview?'':`<section>${sectionTitle('Choisir une licence','La réservation ouvre une discussion, elle ne déclenche aucun paiement.')}${licenses.length?`<div class="license-grid">${licenses.map(l=>`<article class="license-card"><span class="eyebrow">Licence</span><h3>${esc(l.name)}</h3><strong class="beat-price">${money(l.price)}</strong><p>${esc(l.description)}</p><small>${esc(l.terms)}</small>${available?`<button class="btn primary full" data-reserve="${beat.id}" data-license="${esc(l.name)}">Réserver cette licence</button>`:'<button class="btn subtle full" disabled>Production indisponible</button>'}</article>`).join('')}</div>`:'<div class="empty-state"><strong>Aucune licence active</strong></div>'}</section>`}</div>`;
 return state.user?appShell(beat.title,privatePreview?'Aperçu privé':'Détail de la production',body):publicShell(body);
}
async function profilePage(ref){
 const profile=await resolveProfile(ref);if(!profile)return notFound();
 const own=state.user&&(authUserId(state.user)===profile.user_id||isAdmin());
 const [beats,badges,blocked,isFollowing,followStats]=await Promise.all([service.listBeats({producer_id:profile.user_id,publicOnly:true}),service.getProfileBadges(profile.user_id),state.user?service.listBlockedUsers(state.user):[],state.user&&!own?service.isFollowing(state.user,profile.user_id):false,service.followStats(profile.user_id)]);
 const t=profile.theme||{},isBlocked=blocked.some(x=>x.blocked_id===profile.user_id),socials=Object.entries(profile.socials||{}).filter(([,v])=>v),followerCount=followStats?.followers??profile.followers??0;
 updateSeo({title:profile.name,description:profile.bio||`${rolesLabel(profile)} sur DanaTrap RSX`,image:mediaUrl(profile.banner||profile.avatar||'',profile.updated_at||''),url:location.href,type:'profile'});
 const followButton=state.user&&!own?`<button class="btn ${isFollowing?'subtle':'profile-btn'}" data-follow-user="${profile.user_id}" data-following="${isFollowing?'true':'false'}">${isFollowing?'✓ Abonné':'Suivre'}</button>`:'';
 const body=`<div class="profile-universe public-profile-v6 effect-${esc(t.profileEffect||'none')} frame-${esc(t.frameStyle||'glass')}" style="${themeVars(t)};${t.backgroundImage?`--profile-bg-image:url('${esc(t.backgroundImage)}')`:''}"><div class="profile-ambient"></div><div class="profile-banner" style="${profile.banner?`background-image:url('${esc(profile.banner)}');background-size:cover;background-position:center`:''}"></div><section class="custom-profile-head">${profileAvatar(profile,'large')}<div class="profile-bio"><span class="eyebrow">${esc(rolesLabel(profile))}</span><h1>${esc(profile.name)} ${profile.verified?'<span class="verified">✓</span>':''}</h1>${badgeMarkup(badges)}<span>${esc(profile.username)} · ${esc(profile.location||'Localisation non renseignée')}</span><p>${esc(profile.bio)}</p><div class="social-row">${socials.map(([k,v])=>`<span>${esc(k)} · ${esc(v)}</span>`).join('')}</div></div><div class="profile-actions">${own?'<a class="btn primary" href="#/app/personnalisation">Personnaliser ma page</a>':followButton}<button class="btn subtle" data-share-title="${esc(profile.name)}" data-share-text="${esc(profile.bio||rolesLabel(profile))}">${icon('share')} Partager</button>${state.user&&!own?`<button class="btn subtle" data-block-user="${profile.user_id}">${isBlocked?'Débloquer':'Bloquer'}</button><button class="btn subtle" data-report-type="profile" data-report-id="${profile.user_id}">Signaler</button>`:''}</div></section><div class="profile-public-stats"><div><strong data-follower-count="${profile.user_id}">${fmt(followerCount)}</strong><span>abonnés</span></div><div><strong>${fmt(profile.plays)}</strong><span>écoutes</span></div><div><strong>${beats.length}</strong><span>productions</span></div></div><section class="profile-public-content profile-main">${rolesOf(profile).includes('Beatmaker')||beats.length?`${sectionTitle('Productions','Catalogue public de ce beatmaker.')}${beatGrid(beats)}`:`${sectionTitle('Projets publics','Collaborations et activité de ce créateur.')}<div class="empty-state"><strong>Aucun projet public pour le moment</strong></div>`}</section></div>`;
 return state.user?appShell(profile.name,`${rolesLabel(profile)} · Profil public`,body):publicShell(body);
}

async function directory(role){const profiles=await service.listProfiles(role,state.directoryQuery);const label=role==='Beatmaker'?'Beatmakers':'Artistes';const content=`<div class="stack"><section class="directory-hero"><div><span class="badge">Annuaire complet</span><h2>${label}</h2><p>Recherche un membre par nom, univers, bio ou localisation.</p></div><label class="search-box">${icon('search')}<input id="directory-search" value="${esc(state.directoryQuery)}" placeholder="Rechercher un ${role.toLowerCase()}…"></label></section><section>${sectionTitle(`${profiles.length} profil${profiles.length>1?'s':''}`,'Chaque page peut avoir ses propres couleurs, cadres, effets et médias.')}${profileGrid(profiles)}</section></div>`;return appShell(label,'Annuaire de la communauté',content);}

async function followingFeedPage(){
 const [feed,followed,suggestions]=await Promise.all([service.activityFeed(state.user,40),service.followedProfiles(state.user),service.listProfiles('Beatmaker')]);
 const suggested=suggestions.filter(p=>p.user_id!==authUserId(state.user)&&!followed.some(x=>x.user_id===p.user_id)).slice(0,4);
 const content=`<div class="stack"><section class="feed-hero"><div><span class="badge">${icon('feed')} Ton réseau</span><h2>L’activité des créateurs que tu suis.</h2><p>Nouvelles productions, profils et univers réunis dans un seul fil.</p></div><a class="btn primary" href="#/app/beatmakers">Découvrir des créateurs</a></section>${followed.length?`<section>${sectionTitle('Profils suivis',`${followed.length} abonnement${followed.length>1?'s':''}`)}<div class="followed-strip">${followed.map(p=>`<a href="#/profile/${p.slug||p.user_id}">${profileAvatar(p,'small')}<span><strong>${esc(p.name)}</strong><small>${esc(rolesLabel(p))}</small></span></a>`).join('')}</div></section>`:''}<section>${sectionTitle('Fil d’activité','Les publications les plus récentes.')}${feed.length?`<div class="activity-feed">${feed.map(item=>`<article class="feed-item"><div class="feed-item-head">${profileAvatar(item.profile,'small')}<div><a href="#/profile/${item.profile?.slug||item.beat.producer_id}"><strong>${esc(item.profile?.name||item.beat.producer_name)}</strong></a><small>a publié une production · ${timeAgo(item.created_at)}</small></div></div>${beatCard(item.beat)}</article>`).join('')}</div>`:'<div class="empty-state"><strong>Aucune publication pour le moment</strong><p>Suis quelques créateurs pour construire ton fil.</p></div>'}</section>${suggested.length?`<section>${sectionTitle('Suggestions','Des beatmakers à découvrir.')}${profileGrid(suggested)}</section>`:''}</div>`;
 updateSeo({title:'Abonnements',description:'Le fil des créateurs suivis sur DanaTrap RSX.'});
 return appShell('Abonnements','Fil des créateurs suivis',content);
}
async function onboardingPage(){
 const [profile,prefs]=await Promise.all([resolveProfile(authUserId(state.user)),service.getRecommendationPreferences(state.user)]),genres=['Trap','Drill','Afro','R&B','Dancehall','Pop urbaine','Old School','Cinématique'],keys=['C min','D min','E min','F min','F# min','G min','A min','B min'];
 const content=`<div class="onboarding-page"><section class="onboarding-intro"><span class="badge">${icon('welcome')} Bienvenue sur DanaTrap RSX</span><h2>Configure ton expérience en quelques minutes.</h2><p>Ces choix alimentent uniquement tes recommandations. Tu pourras les modifier plus tard.</p></section><form id="onboarding-form" class="onboarding-form"><section class="panel"><span class="onboarding-step">1</span><h3>Ton profil</h3><div class="form-grid"><label>Localisation<input name="location" value="${esc(profile?.location||'')}"></label><label class="wide">Biographie<textarea name="bio" placeholder="Présente ton univers, tes influences et tes projets.">${esc(profile?.bio||'')}</textarea></label></div></section><section class="panel"><span class="onboarding-step">2</span><h3>Genres préférés</h3><div class="onboarding-checks">${genres.map(g=>`<label><input type="checkbox" name="genres" value="${esc(g)}" ${checked((prefs.preferred_genres||[]).includes(g))}> ${esc(g)}</label>`).join('')}</div></section><section class="panel"><span class="onboarding-step">3</span><h3>BPM et tonalités</h3><div class="form-grid"><label>BPM minimum<input type="number" name="bpm_min" min="50" max="220" value="${prefs.preferred_bpm_min||80}"></label><label>BPM maximum<input type="number" name="bpm_max" min="50" max="220" value="${prefs.preferred_bpm_max||160}"></label></div><div class="onboarding-checks">${keys.map(k=>`<label><input type="checkbox" name="keys" value="${esc(k)}" ${checked((prefs.preferred_keys||[]).includes(k))}> ${esc(k)}</label>`).join('')}</div></section><section class="panel"><span class="onboarding-step">4</span><h3>Notifications</h3><label class="toggle-row"><span><strong>Recevoir les nouveautés par e-mail</strong><small>Le choix sera enregistré dans tes préférences.</small></span><input type="checkbox" name="email" ${checked(profile?.notification_preferences?.email!==false)}></label><label class="toggle-row"><span><strong>Notifications navigateur</strong></span><input type="checkbox" name="browser" ${checked(profile?.notification_preferences?.browser!==false)}></label></section><div class="onboarding-actions"><button class="btn subtle" type="button" data-skip-onboarding>Passer pour le moment</button><button class="btn primary" type="submit">Terminer la configuration</button></div></form></div>`;
 return appShell('Bienvenue','Configuration personnalisée',content);
}

