 const renderWaveform=(focusRatio=null)=>{if(destroyed)return;const oldWidth=Math.max(1,stageWidth||stage.offsetWidth||scroll.clientWidth),centerRatio=focusRatio==null?clamp((scroll.scrollLeft+scroll.clientWidth/2)/oldWidth):clamp(focusRatio),height=132,dpr=Math.min(2,window.devicePixelRatio||1),width=Math.max(scroll.clientWidth*zoom,480);stageWidth=width;stage.style.width=`${width}px`;const baseCtx=prepareCanvas(baseCanvas,width,height,dpr),playedCtx=prepareCanvas(playedCanvas,width,height,dpr);paintWave(baseCtx,width,height,'rgba(231,233,239,.34)');paintWave(playedCtx,width,height,getComputedStyle(document.documentElement).getPropertyValue('--yellow').trim()||'#f6c90e');updatePlaybackVisual();updateSelectionVisual();requestAnimationFrame(()=>{scroll.scrollLeft=Math.max(0,Math.min(width-scroll.clientWidth,centerRatio*width-scroll.clientWidth/2));});};
