function imageDataUrl(file,max=1400,quality=.84){if(!file)return Promise.resolve('');if(file.type==='image/svg+xml')return fileDataUrl(file);return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL(file.type==='image/png'?'image/png':'image/webp',quality));};img.onerror=e=>{URL.revokeObjectURL(url);reject(e)};img.src=url;});}
